input.command:
X=/tmp/probe/work-progress-jobs-files/X
run(){ cd $X; printf '=== -i %q  ->  ' "$1"; /workspace/executable --debug-ignore -i "$1" ig > /tmp/_o 2>/tmp/_e; ec=$?; printf 'exit=%s\n' $ec; sed -n 's/^ignored path: /   IGN: /p;s/^Checking \(.*\) \.\.\.$/   CHK: \1/p' /tmp/_o; if [ -s /tmp/_e ]; then echo "   ERR:"; cat /tmp/_e; fi; }
for p in "test" "test/" "/test" "ig/test" "ig/test/" "./test" "*/test" "**/test" "*test*" "src" "src/gen" "gen" "main.c" "src/main.c" "/main.c" "*.cpp" "*cpp" "t?.c" "t*.c" "gen1.c" "ig" "ig/" "*" "**" "" ; do run "$p"; done

X=/tmp/probe/work-progress-jobs-files/X
run(){ cd $X; printf '=== -i %-22q -> ' "$1"; /workspace/executable --debug-ignore -i "$1" -q ig > /tmp/_o 2>/tmp/_e; ec=$?; printf 'exit=%s : ' $ec; sed -n 's/^ignored path: //p' /tmp/_o | tr '\n' ' ' ; echo; }
for p in "m*n.c" "*ain.c" "mai?.c" "ma*" "ig/**/gen1.c" "ig/*/gen1.c" "**/gen1.c" "ig/**" "ig/*" "g/build" "g*/build" "*g/build" "a" "src/gen/" "**/" "*/" "src/*" "src/**" "ig/src/main.c" "/ig/src/main.c" ; do run "$p"; done

P=/tmp/probe/work-progress-jobs-files
run(){ cd $P; printf '=== -i %-16q arg=%s -> ' "$1" "$2"; /workspace/executable --debug-ignore -i "$1" -q "$2" > /tmp/_o 2>/tmp/_e; ec=$?; printf 'exit=%s : ' $ec; sed -n 's/^ignored path: //p' /tmp/_o | tr '\n' ' ' ; echo; if [ -s /tmp/_e ]; then echo "  ERR: $(cat /tmp/_e)"; fi; }
for p in "ig" "ig/" "*/" "**/" "X/ig/" "X/" "X" "/" "//" "X/ig" "testing/" "b.cpp/" "*/test/" "ig//test" ; do run "$p" X/ig; done

X=/tmp/probe/work-progress-jobs-files/X; RX=/tmp/probe/work-progress-jobs-files/runx.sh
ff(){ cd $X; printf '=== --file-filter=%-16q -> ' "$1"; /workspace/executable --file-filter="$1" ig > /tmp/_o 2>/tmp/_e; ec=$?; printf 'exit=%s : ' $ec; sed -n 's/^Checking \(.*\) \.\.\.$/\1/p' /tmp/_o | tr '\n' ' '; echo; if [ -s /tmp/_e ]; then echo "  ERR: $(cat /tmp/_e)"; fi; }
for f in "*.cpp" "*main.c" "main.c" "ig/src/main.c" "src/main.c" "*/main.c" "**/main.c" "ig/*" "ig/**" "*" "**" "*.c" "t?.c" "ig/test/*" "nomatch*" "" ; do ff "$f"; done

X=/tmp/probe/work-progress-jobs-files/X; mkdir -p $X/rp/sub
cat > $X/rp/sub/err.c <<'EOF'
int f(void) {
    int a[2];
    a[5] = 1;
    return a[0];
}
EOF
cd $X/rp && printf '### baseline\n'; /workspace/executable sub/err.c > /tmp/_o 2>/tmp/_e; echo "exit=$?"; cat -A /tmp/_o; echo "--err"; cat -A /tmp/_e
